279:   static const char *const names[] = {"format_version",      "token_kid",
280:                                       "token_jwk",           "manifest_wire_id",
281:                                       "manifest_public_key", "publication_hwm_identity_digest",
282:                                       "bundle_sha256"};
283:   const cJSON *v[7];
284:   char jwk[768], kid[65], manifest_id[65], manifest_b64[64], publication[65];
285:   unsigned char digest[32];
286:   char digest_hex[65], preimage[SERVER_MGMT_JWKS_BUNDLE_MAX],
287:       expected[SERVER_MGMT_JWKS_BUNDLE_MAX];
288:   size_t manifest_n = 0;
289:   int ok = root && exact_object(root, names, 7, v) && cJSON_IsNumber(v[0]) &&
290:            v[0]->valuedouble == 1 && cJSON_IsString(v[1]) && cJSON_IsObject(v[2]) &&
291:            cJSON_IsString(v[3]) && cJSON_IsString(v[4]) && cJSON_IsString(v[5]) &&
292:            cJSON_IsString(v[6]) && validate_jwk(v[2], jwk, sizeof(jwk), kid) == 0 &&
293:            strcmp(kid, v[1]->valuestring) == 0 && strlen(v[4]->valuestring) == 43 &&
294:            b64_decode(v[4]->valuestring, 43, out->manifest_public, sizeof(out->manifest_public),
295:                       &manifest_n) == 0 &&
296:            manifest_n == 32 && lower_hex(v[5]->valuestring, 64) &&
