304:   hex_encode(manifest_digest, 16, manifest_id + 16);
305:   if (strcmp(manifest_id, v[3]->valuestring))
306:      goto done;
307:   snprintf(manifest_b64, sizeof(manifest_b64), "%s", v[4]->valuestring);
308:   snprintf(publication, sizeof(publication), "%s", v[5]->valuestring);
309:   int pn = snprintf(preimage, sizeof(preimage),
310:                     "{\"format_version\":1,\"token_kid\":\"%s\",\"token_jwk\":%s,"
311:                     "\"manifest_wire_id\":\"%s\",\"manifest_public_key\":\"%s\","
312:                     "\"publication_hwm_identity_digest\":\"%s\"}",
313:                     kid, jwk, manifest_id, manifest_b64, publication);
314:   if (pn < 1 || (size_t)pn >= sizeof(preimage) || sha256(preimage, (size_t)pn, digest))
315:      goto done;
316:   hex_encode(digest, 32, digest_hex);
317:   int en = snprintf(expected, sizeof(expected), "%.*s,\"bundle_sha256\":\"%s\"}", pn - 1, preimage,
318:                     digest_hex);
