205:/* The readiness decision, as a pure function of a snapshot and a clock: no
206: * globals, no locks, no I/O. Split out so staleness and roll-up behavior can be
207: * tested deterministically by passing a `now` rather than sleeping past a real
208: * interval. `db1_ok`/`kb_ok` are 1 ok, 0 fail, -1 unknown/not-sampled. */
209:int server_ready_render(int db1_ok, int kb_ok, const server_ready_diagnostics_t *diagnostics,
210:                        long sampled_at, long now, int stale_secs, char *resp, int cap)
211:{
212:   dep_state_t db1 = (db1_ok > 0) ? DEP_OK : (db1_ok == 0 ? DEP_FAIL : DEP_UNKNOWN);
213:   dep_state_t kb = (kb_ok > 0) ? DEP_OK : (kb_ok == 0 ? DEP_FAIL : DEP_UNKNOWN);
214:   int retrieval_ok = diagnostics ? diagnostics->retrieval_ok : -1;
215:   dep_state_t retrieval =
216:       (retrieval_ok > 0) ? DEP_OK : (retrieval_ok == 0 ? DEP_FAIL : DEP_UNKNOWN);
217:
218:   long age = (sampled_at > 0) ? (now - sampled_at) : -1;
219:
220:   /* Never sampled, or too old to trust — including a snapshot stamped in the
221:    * future, which means the clock moved and the age is meaningless. Degrade to
222:    * unknown so a wedged sampler cannot keep advertising a stale "ready". */
223:   int stale = (sampled_at <= 0) || (age < 0) || (age > (long)stale_secs);
224:   if (stale)
225:   {
226:      db1 = DEP_UNKNOWN;
227:      kb = DEP_UNKNOWN;
228:      retrieval = DEP_UNKNOWN;
229:   }
230:
231:   int ready = (db1 == DEP_OK && kb == DEP_OK && retrieval == DEP_OK);
232:   const char *status = ready ? "ok" : (stale ? "unknown" : "degraded");
233:
234:   if (stale && (sampled_at <= 0 || age < 0))
235:      snprintf(resp, (size_t)cap,
236:               "{\"ready\":false,\"status\":\"unknown\",\"service\":\"aimee-server\","
237:               "\"sampled_at\":null,\"age_seconds\":null,"
238:               "\"dependencies\":{\"db1\":\"unknown\",\"kb\":\"unknown\","
239:               "\"retrieval\":\"unknown\"},\"diagnostics\":{\"breaker_state\":\"unknown\","
240:               "\"failed_boundary\":\"unknown\",\"retry_after_ms\":0,"
241:               "\"last_success_query_ms\":0,\"last_ingest_at\":\"\"}}");
242:   else
243:   {
244:      char escaped_boundary[64];
245:      char escaped_breaker[64];
246:      char escaped_ingest[256];
247:      json_escape(diagnostics ? diagnostics->failed_boundary : NULL, escaped_boundary,
248:                  sizeof(escaped_boundary));
249:      json_escape(diagnostics ? diagnostics->breaker_state : NULL, escaped_breaker,
250:                  sizeof(escaped_breaker));
251:      json_escape(diagnostics ? diagnostics->last_ingest_at : NULL, escaped_ingest,
252:                  sizeof(escaped_ingest));
253:      snprintf(resp, (size_t)cap,
254:               "{\"ready\":%s,\"status\":\"%s\",\"service\":\"aimee-server\","
255:               "\"sampled_at\":%ld,\"age_seconds\":%ld,"
256:               "\"dependencies\":{\"db1\":\"%s\",\"kb\":\"%s\",\"retrieval\":\"%s\"},"
257:               "\"diagnostics\":{\"failed_boundary\":\"%s\",\"breaker_state\":\"%s\","
258:               "\"retry_after_ms\":%lld,"
259:               "\"last_success_query_ms\":%lld,\"last_ingest_at\":\"%s\"}}",
260:               ready ? "true" : "false", status, sampled_at, age, dep_name(db1), dep_name(kb),
261:               dep_name(retrieval), escaped_boundary, escaped_breaker,
262:               diagnostics ? diagnostics->retry_after_ms : 0,
263:               diagnostics ? diagnostics->last_success_query_ms : 0, escaped_ingest);
264:   }
265:
266:   return ready ? 200 : 503;
267:}
