137:static int b64_decode(const char *in, size_t n, unsigned char *out, size_t cap, size_t *out_n)
138:{
139:   if (!in || !n || !out || !out_n || n % 4 == 1)
140:      return -1;
141:   uint32_t acc = 0;
142:   unsigned bits = 0;
143:   size_t used = 0;
144:   for (size_t i = 0; i < n; ++i)
145:   {
146:      int v = b64_value((unsigned char)in[i]);
147:      if (v < 0)
