149:      acc = (acc << 6) | (uint32_t)v;
150:      bits += 6;
151:      if (bits >= 8)
152:      {
153:         bits -= 8;
154:         if (used == cap)
155:            return -1;
156:         out[used++] = (unsigned char)(acc >> bits);
157:         acc &= bits ? ((UINT32_C(1) << bits) - 1) : 0;
158:      }
159:   }
160:   if (acc)
161:      return -1;
162:   *out_n = used;
163:   return 0;
164:}
