215:static void put_u32be(unsigned char out[4], uint32_t v)
216:{
217:   out[0] = (unsigned char)(v >> 24);
218:   out[1] = (unsigned char)(v >> 16);
219:   out[2] = (unsigned char)(v >> 8);
