154:/* Sample every dependency into a local snapshot, then publish it under the
155: * lock in one assignment so a concurrent reader sees the previous snapshot or
156: * this one, never a half-written mix. */
157:void server_ready_sample_now(void)
158:{
159:   ready_snapshot_t s;
160:   memset(&s, 0, sizeof(s));
161:
162:   s.db1 = db1_is_initialized() ? DEP_OK : DEP_FAIL;
163:
164:   kb_health_t h;
165:   memset(&h, 0, sizeof(h));
166:   s.kb = (kb_client_health(&h) == 0 && h.process_ok) ? DEP_OK : DEP_FAIL;
167:   kb_client_dependency_health_t dependency;
168:   kb_client_dependency_health(&dependency);
169:   snprintf(s.breaker_state, sizeof(s.breaker_state), "%s", dependency.state);
170:   s.retry_after_ms = dependency.retry_after_ms;
171:   s.last_success_query_ms = dependency.last_success_ms;
172:   snprintf(s.last_ingest_at, sizeof(s.last_ingest_at), "%s", h.last_ingest_at);
173:   s.retrieval = (s.kb == DEP_OK && h.db2_ok && h.db2_kb_tables_ok && h.pgvec_ok &&
174:                  h.pgvec_collection_ok && h.embed_ok && strcmp(dependency.state, "open") != 0)
175:                     ? DEP_OK
176:                     : DEP_FAIL;
177:   const char *failed = s.kb != DEP_OK                          ? "kb_transport"
178:                        : !h.db2_ok                             ? "db2"
179:                        : !h.db2_kb_tables_ok                   ? "kb_schema"
180:                        : !h.pgvec_ok                           ? "pgvector"
181:                        : !h.pgvec_collection_ok                ? "vector_collection"
182:                        : !h.embed_ok                           ? "embedder"
183:                        : strcmp(dependency.state, "open") == 0 ? "kb_breaker"
184:                                                                : "";
185:   snprintf(s.failed_boundary, sizeof(s.failed_boundary), "%s", failed);
186:
187:   s.sampled_at = (long)time(NULL);
188:
189:   pthread_mutex_lock(&g_ready_mtx);
190:   g_snap = s;
191:   pthread_mutex_unlock(&g_ready_mtx);
192:}
