13:static pthread_t g_thread;
14:static atomic_int g_running;
15:static int g_started;
16:
17:/* The wizard creates the managed KB (and therefore its hostname-valid server
18: * certificate) after aimee-server is already running. The startup JWKS fetch is
19: * intentionally fail-closed, but a one-shot failure must not require an
20: * operator restart: the first authenticated heartbeat proves the same mTLS
21: * identity can now reach the KB, so retry the signed-artifact fetch at that
22: * point. Token verification continues to own later generation refreshes. */
23:static int management_jwks_ready(void)
24:{
25:   const char *trust_path = getenv("AIMEE_SERVER_MGMT_JWKS_TRUST_BUNDLE");
26:   if (!trust_path || !trust_path[0])
27:      return 1; /* Management authorization is not configured for this server. */
28:   return server_mgmt_jwks_cache_startup(trust_path, (int64_t)time(NULL),
29:                                         kb_client_mtls_management_jwks_fetch,
30:                                         NULL) == SERVER_MGMT_JWKS_CACHE_OK;
31:}
32:
33:static void *heartbeat_main(void *unused)
34:{
35:   (void)unused;
36:   int jwks_ready = 0;
37:   while (atomic_load(&g_running))
38:   {
39:      char server_id[128];
40:      int ready = server_runtime_server_id_load(server_id, sizeof(server_id)) &&
41:                  kb_client_mtls_configured();
42:      if (ready)
43:      {
44:         if (kb_client_mtls_heartbeat(server_id, "ready", AIMEE_VERSION) != 0)
45:            LOG_WARN("server.kb", "server registry heartbeat rejected for %s", server_id);
46:         else if (!jwks_ready && management_jwks_ready())
47:         {
48:            jwks_ready = 1;
49:            LOG_INFO("server.mgmt", "management JWKS authorization ready");
50:         }
51:      }
52:      /* Before the wizard's one-shot writes the identity, poll quickly. Once
53:       * enrolled, return to the ordinary 30-second registry cadence. */
54:      int interval = ready ? 30 : 1;
55:      for (int i = 0; i < interval && atomic_load(&g_running); i++)
56:      {
57:         struct timespec delay = {1, 0};
58:         nanosleep(&delay, NULL);
59:      }
60:   }
61:   return NULL;
62:}
63:
64:int server_kb_heartbeat_start(void)
65:{
66:   atomic_store(&g_running, 1);
67:   if (pthread_create(&g_thread, NULL, heartbeat_main, NULL) != 0)
68:   {
69:      atomic_store(&g_running, 0);
70:      return -1;
71:   }
72:   g_started = 1;
73:   return 0;
74:}
75:
76:void server_kb_heartbeat_stop(void)
77:{
78:   if (!g_started)
79:      return;
80:   atomic_store(&g_running, 0);
81:   pthread_join(g_thread, NULL);
82:   g_started = 0;
83:}

