18:static const char *tier_text(kb_identity_tier_t tier)
19:{
20:   switch (tier)
21:   {
22:   case KB_IDENTITY_TIER_OFF:
23:      return "off";
24:   case KB_IDENTITY_TIER_DATA:
25:      return "data";
26:   case KB_IDENTITY_TIER_FULL:
27:      return "full";
28:   }
29:   return NULL;
30:}
