31:int server_mgmt_jwks_trust_bundle_load(const char *absolute_path, char *out, size_t cap,
32:                                       size_t *out_len)
33:{
34:   if (out && cap)
35:      memset(out, 0, cap);
36:   if (out_len)
37:      *out_len = 0;
38:   if (!absolute_path || absolute_path[0] != '/' || !out || !out_len ||
39:       cap < SERVER_MGMT_JWKS_BUNDLE_MAX)
40:      return -1;
41:   int fd = open(absolute_path, O_RDONLY | O_CLOEXEC | O_NOFOLLOW);
42:   struct stat st;
43:   if (fd < 0 || fstat(fd, &st) || !S_ISREG(st.st_mode) || st.st_uid != 0 || st.st_nlink != 1 ||
44:       (st.st_mode & (S_IWGRP | S_IWOTH)) || st.st_size < 1 ||
45:       st.st_size >= SERVER_MGMT_JWKS_BUNDLE_MAX)
46:   {
47:      if (fd >= 0)
48:         close(fd);
49:      return -1;
50:   }
51:   size_t used = 0;
52:   while (used < (size_t)st.st_size)
53:   {
54:      ssize_t n = read(fd, out + used, (size_t)st.st_size - used);
55:      if (n <= 0)
56:      {
57:         close(fd);
58:         memset(out, 0, cap);
59:         return -1;
60:      }
61:      used += (size_t)n;
62:   }
63:   char extra;
64:   ssize_t trailing = read(fd, &extra, 1);
65:   close(fd);
66:   if (trailing != 0 || memchr(out, '\0', used))
67:   {
68:      memset(out, 0, cap);
69:      return -1;
70:   }
71:   /* Both offline export binaries use a terminal newline as stdout framing.
72:    * A direct, documented `... --export-public > bundle.json` must therefore
73:    * load as the canonical JSON bytes rather than fail because the framing byte
74:    * was mistaken for signed content. Accept exactly one LF (or CRLF), while an
75:    * extra newline/internal whitespace still fails the byte-exact parser. */
76:   if (used && out[used - 1] == '\n')
77:   {
78:      used--;
79:      if (used && out[used - 1] == '\r')
80:         used--;
81:   }
82:   out[used] = '\0';
83:   trust_t trust;
84:   if (trust_parse(out, used, &trust))
85:   {
86:      memset(out, 0, cap);
87:      return -1;
88:   }
89:   OPENSSL_cleanse(&trust, sizeof(trust));
90:   *out_len = used;
91:   return 0;
92:}
