94:static int sha256(const void *value, size_t len, unsigned char out[32])
95:{
96:   unsigned int n = 0;
97:   if ((!value && len) || EVP_Digest(value, len, out, &n, EVP_sha256(), NULL) != 1 || n != 32)
98:   {
99:      OPENSSL_cleanse(out, 32);
100:      return -1;
101:   }
102:   return 0;
103:}
