105:static void hex_encode(const unsigned char *in, size_t n, char *out)
106:{
107:   static const char hex[] = "0123456789abcdef";
108:   for (size_t i = 0; i < n; ++i)
109:   {
110:      out[i * 2] = hex[in[i] >> 4];
111:      out[i * 2 + 1] = hex[in[i] & 15];
112:   }
113:   out[n * 2] = '\0';
114:}
