126:static int b64_value(unsigned char c)
127:{
128:   if (c >= 'A' && c <= 'Z')
129:      return c - 'A';
130:   if (c >= 'a' && c <= 'z')
131:      return c - 'a' + 26;
132:   if (c >= '0' && c <= '9')
133:      return c - '0' + 52;
134:   return c == '-' ? 62 : (c == '_' ? 63 : -1);
135:}
136:
137:static int b64_decode(const char *in, size_t n, unsigned char *out, size_t cap, size_t *out_n)
138:{
139:   if (!in || !n || !out || !out_n || n % 4 == 1)
140:      return -1;
141:   uint32_t acc = 0;
142:   unsigned bits = 0;
143:   size_t used = 0;
144:   for (size_t i = 0; i < n; ++i)
145:   {
146:      int v = b64_value((unsigned char)in[i]);
147:      if (v < 0)
148:         return -1;
149:      acc = (acc << 6) | (uint32_t)v;
150:      bits += 6;
151:      if (bits >= 8)
152:      {
153:         bits -= 8;
154:         if (used == cap)
155:            return -1;
156:         out[used++] = (unsigned char)(acc >> bits);
157:         acc &= bits ? ((UINT32_C(1) << bits) - 1) : 0;
158:      }
159:   }
160:   if (acc)
161:      return -1;
162:   *out_n = used;
163:   return 0;
164:}
