166:static int no_duplicates(const cJSON *item)
167:{
168:   if (!item)
169:      return 1;
170:   if (cJSON_IsObject(item))
171:      for (const cJSON *a = item->child; a; a = a->next)
172:         for (const cJSON *b = a->next; b; b = b->next)
173:            if (!a->string || !b->string || strcmp(a->string, b->string) == 0)
174:               return 0;
175:   for (const cJSON *p = item->child; p; p = p->next)
176:      if (!no_duplicates(p))
177:         return 0;
178:   return 1;
179:}
