147:   if (claims_out)
148:      memset(claims_out, 0, sizeof(*claims_out));
149:
150:   /* Report an absent credential before doing any work, so the ordinary
151:    * read-only caller is never mistaken for a misconfiguration. */
152:   if (!token || token_len == 0 || token[0] == '\0')
153:   {
154:      *outcome = SERVER_WRITE_TIER_ABSENT;
155:      return SERVER_REMOTE_WRITES_OFF;
