74:/* Parse a positive integer env override. Malformed input falls back to the
75: * documented default and says so, rather than silently becoming zero (which is
76: * what atoi() would do) — a mistyped interval should be visible, not turn into
77: * a different policy nobody chose. */
78:static int env_int(const char *name, int dflt, int min, int max)
79:{
80:   const char *v = getenv(name);
81:   if (!v || !v[0])
82:      return dflt;
83:
84:   errno = 0;
85:   char *end = NULL;
86:   long n = strtol(v, &end, 10);
87:   if (errno != 0 || !end || *end != '\0' || n < (long)min || n > (long)max)
88:   {
89:      LOG_ERROR("ready", "%s=\"%s\" is not an integer in [%d,%d]; using %d", name, v, min, max,
90:                dflt);
91:      return dflt;
92:   }
93:   return (int)n;
94:}
