28:   return server_mgmt_jwks_cache_startup(trust_path, (int64_t)time(NULL),
29:                                         kb_client_mtls_management_jwks_fetch,
30:                                         NULL) == SERVER_MGMT_JWKS_CACHE_OK;
31:}
