64:int server_kb_heartbeat_start(void)
65:{
66:   atomic_store(&g_running, 1);
67:   if (pthread_create(&g_thread, NULL, heartbeat_main, NULL) != 0)
68:   {
69:      atomic_store(&g_running, 0);
70:      return -1;
71:   }
72:   g_started = 1;
73:   return 0;
74:}
