181:static int exact_object(const cJSON *object, const char *const *names, size_t count,
182:                        const cJSON **values)
183:{
184:   if (!cJSON_IsObject(object))
185:      return 0;
186:   memset(values, 0, count * sizeof(*values));
187:   size_t seen = 0;
188:   for (const cJSON *p = object->child; p; p = p->next)
189:   {
190:      size_t i = 0;
191:      while (i < count && (!p->string || strcmp(p->string, names[i])))
192:         ++i;
193:      if (i == count || values[i])
194:         return 0;
195:      values[i] = p;
196:      ++seen;
197:   }
198:   return seen == count;
199:}
