116:static int lower_hex(const char *s, size_t n)
117:{
118:   if (!s || strlen(s) != n)
119:      return 0;
120:   for (size_t i = 0; i < n; ++i)
121:      if (!((s[i] >= '0' && s[i] <= '9') || (s[i] >= 'a' && s[i] <= 'f')))
122:         return 0;
