273:static int trust_parse(const char *bundle, size_t bundle_n, trust_t *out)
274:{
275:   memset(out, 0, sizeof(*out));
276:   if (!bundle || !bundle_n || bundle_n >= SERVER_MGMT_JWKS_BUNDLE_MAX)
277:      return -1;
278:   cJSON *root = parse_exact(bundle, bundle_n);
279:   static const char *const names[] = {"format_version",      "token_kid",
280:                                       "token_jwk",           "manifest_wire_id",
281:                                       "manifest_public_key", "publication_hwm_identity_digest",
282:                                       "bundle_sha256"};
283:   const cJSON *v[7];
284:   char jwk[768], kid[65], manifest_id[65], manifest_b64[64], publication[65];
285:   unsigned char digest[32];
286:   char digest_hex[65], preimage[SERVER_MGMT_JWKS_BUNDLE_MAX],
287:       expected[SERVER_MGMT_JWKS_BUNDLE_MAX];
288:   size_t manifest_n = 0;
289:   int ok = root && exact_object(root, names, 7, v) && cJSON_IsNumber(v[0]) &&
290:            v[0]->valuedouble == 1 && cJSON_IsString(v[1]) && cJSON_IsObject(v[2]) &&
291:            cJSON_IsString(v[3]) && cJSON_IsString(v[4]) && cJSON_IsString(v[5]) &&
292:            cJSON_IsString(v[6]) && validate_jwk(v[2], jwk, sizeof(jwk), kid) == 0 &&
293:            strcmp(kid, v[1]->valuestring) == 0 && strlen(v[4]->valuestring) == 43 &&
294:            b64_decode(v[4]->valuestring, 43, out->manifest_public, sizeof(out->manifest_public),
295:                       &manifest_n) == 0 &&
296:            manifest_n == 32 && lower_hex(v[5]->valuestring, 64) &&
297:            lower_hex(v[6]->valuestring, 64);
298:   if (!ok)
299:      goto done;
300:   unsigned char manifest_digest[32];
301:   if (sha256(out->manifest_public, 32, manifest_digest))
302:      goto done;
303:   memcpy(manifest_id, "p5-jwks-root-v1-", 16);
304:   hex_encode(manifest_digest, 16, manifest_id + 16);
305:   if (strcmp(manifest_id, v[3]->valuestring))
306:      goto done;
307:   snprintf(manifest_b64, sizeof(manifest_b64), "%s", v[4]->valuestring);
308:   snprintf(publication, sizeof(publication), "%s", v[5]->valuestring);
309:   int pn = snprintf(preimage, sizeof(preimage),
310:                     "{\"format_version\":1,\"token_kid\":\"%s\",\"token_jwk\":%s,"
311:                     "\"manifest_wire_id\":\"%s\",\"manifest_public_key\":\"%s\","
312:                     "\"publication_hwm_identity_digest\":\"%s\"}",
313:                     kid, jwk, manifest_id, manifest_b64, publication);
314:   if (pn < 1 || (size_t)pn >= sizeof(preimage) || sha256(preimage, (size_t)pn, digest))
315:      goto done;
316:   hex_encode(digest, 32, digest_hex);
317:   int en = snprintf(expected, sizeof(expected), "%.*s,\"bundle_sha256\":\"%s\"}", pn - 1, preimage,
318:                     digest_hex);
319:   if (en < 1 || (size_t)en != bundle_n || CRYPTO_memcmp(expected, bundle, bundle_n) ||
320:       sha256(bundle, bundle_n, out->bundle_digest))
321:      goto done;
322:   snprintf(out->token_kid, sizeof(out->token_kid), "%s", kid);
323:   snprintf(out->token_jwk, sizeof(out->token_jwk), "%s", jwk);
324:   snprintf(out->manifest_id, sizeof(out->manifest_id), "%s", manifest_id);
325:   ok = 1;
326:done:
327:   cJSON_Delete(root);
328:   if (!ok)
329:      memset(out, 0, sizeof(*out));
330:   return ok ? 0 : -1;
331:}
