246:static int validate_jwk(const cJSON *jwk, char *canonical, size_t cap, char kid[65])
247:{
248:   static const char *const names[] = {"kty", "kid", "use", "alg", "n", "e"};
249:   const cJSON *v[6];
250:   if (!exact_object(jwk, names, 6, v))
251:      return -1;
252:   for (size_t i = 0; i < 6; ++i)
253:      if (!cJSON_IsString(v[i]) || !v[i]->valuestring)
254:         return -1;
255:   if (strcmp(v[0]->valuestring, "RSA") || strcmp(v[2]->valuestring, "sig") ||
256:       strcmp(v[3]->valuestring, "RS256") || strcmp(v[5]->valuestring, "AQAB") ||
257:       strlen(v[1]->valuestring) > 64)
258:      return -1;
259:   unsigned char modulus[384];
260:   size_t modulus_n = 0;
261:   if (b64_decode(v[4]->valuestring, strlen(v[4]->valuestring), modulus, sizeof(modulus),
262:                  &modulus_n) ||
263:       modulus_n != sizeof(modulus) || !modulus[0] || derive_kid(modulus, kid) ||
264:       strcmp(kid, v[1]->valuestring))
265:      return -1;
266:   int n = snprintf(canonical, cap,
267:                    "{\"kty\":\"RSA\",\"kid\":\"%s\",\"use\":\"sig\","
268:                    "\"alg\":\"RS256\",\"n\":\"%s\",\"e\":\"AQAB\"}",
269:                    kid, v[4]->valuestring);
270:   return n > 0 && (size_t)n < cap ? 0 : -1;
271:}
