342:static int digest_part(EVP_MD_CTX *md, const void *value, size_t n)
343:{
344:   unsigned char size[4];
345:   if (n > UINT32_MAX)
346:      return -1;
347:   put_u32be(size, (uint32_t)n);
348:   return EVP_DigestUpdate(md, size, 4) == 1 && (!n || EVP_DigestUpdate(md, value, n) == 1) ? 0
349:                                                                                            : -1;
