352:static int manifest_digest(const char *payload, size_t payload_n, const char *manifest_id,
353:                           const unsigned char signature[64], unsigned char out[32])
354:{
355:   static const char domain[] = "aimee.p5.jwks.manifest.v1";
356:   static const char alg[] = "EdDSA";
357:   EVP_MD_CTX *md = EVP_MD_CTX_new();
358:   unsigned int n = 0;
359:   int ok = md && EVP_DigestInit_ex(md, EVP_sha256(), NULL) == 1 &&
360:            !digest_part(md, domain, sizeof(domain) - 1) && !digest_part(md, payload, payload_n) &&
361:            !digest_part(md, manifest_id, strlen(manifest_id)) &&
362:            !digest_part(md, alg, sizeof(alg) - 1) && !digest_part(md, signature, 64) &&
363:            EVP_DigestFinal_ex(md, out, &n) == 1 && n == 32;
364:   EVP_MD_CTX_free(md);
365:   return ok ? 0 : -1;
366:}
