269:/* Serve the snapshot. Performs no I/O: a locked copy, then a pure render. */
270:static int ready_provider(char *resp, int cap)
271:{
272:   pthread_mutex_lock(&g_ready_mtx);
273:   ready_snapshot_t s = g_snap;
274:   pthread_mutex_unlock(&g_ready_mtx);
275:
276:   int db1_ok = (s.db1 == DEP_UNKNOWN) ? -1 : (s.db1 == DEP_OK);
277:   int kb_ok = (s.kb == DEP_UNKNOWN) ? -1 : (s.kb == DEP_OK);
278:   server_ready_diagnostics_t diagnostics = {
279:       .retrieval_ok = (s.retrieval == DEP_UNKNOWN) ? -1 : (s.retrieval == DEP_OK),
280:       .failed_boundary = s.failed_boundary,
281:       .breaker_state = s.breaker_state,
282:       .retry_after_ms = s.retry_after_ms,
283:       .last_success_query_ms = s.last_success_query_ms,
284:       .last_ingest_at = s.last_ingest_at,
285:   };
286:
287:   return server_ready_render(db1_ok, kb_ok, &diagnostics, s.sampled_at, (long)time(NULL),
288:                              ready_stale_secs(), resp, cap);
289:}
