98:/* Assemble the resolver config from this server's environment and JWKS cache.
99: * Returns 1 on success. On failure sets *outcome to the specific reason so the
100: * caller never has to guess whether the problem was the token or the server. */
101:static int build_config(server_write_tier_config_t *config, char *jwks, size_t jwks_cap,
102:                        int64_t *team, char *bundle, size_t bundle_cap, int64_t now,
103:                        server_write_tier_outcome_t *outcome)
104:{
105:   memset(config, 0, sizeof(*config));
106:   char server_id[128];
107:   if (server_runtime_identity_load(server_id, sizeof(server_id), team) !=
108:       SERVER_RUNTIME_IDENTITY_READY)
109:   {
110:      *outcome = SERVER_WRITE_TIER_NO_TEAM_CONFIGURED;
111:      return 0;
112:   }
113:   const char *bundle_path = getenv("AIMEE_SERVER_MGMT_JWKS_TRUST_BUNDLE");
114:   if (!bundle_path || !bundle_path[0])
115:   {
116:      *outcome = SERVER_WRITE_TIER_INVALID;
117:      return 0;
118:   }
119:   size_t bundle_len = 0, jwks_len = 0;
120:   if (server_mgmt_jwks_trust_bundle_load(bundle_path, bundle, bundle_cap, &bundle_len) != 0 ||
121:       server_mgmt_jwks_cache_load(bundle, bundle_len, now, jwks, jwks_cap, &jwks_len) !=
122:           SERVER_MGMT_JWKS_CACHE_OK ||
123:       jwks_len == 0)
124:   {
125:      /* Without keys we cannot tell a forged token from a good one, so we must
126:       * not guess. */
127:      *outcome = SERVER_WRITE_TIER_INVALID;
128:      return 0;
129:   }
130:   config->jwks_json = jwks;
131:   config->expected_issuer = "kb"; /* proposal §4 pins iss=kb */
132:   config->expected_audience = server_id;
133:   config->enrolled_teams = team;
134:   config->enrolled_team_count = 1; /* a server belongs to exactly one team */
135:   config->replay = server_write_tier_replay_db1;
136:   return 1;
137:}
