33:static void *heartbeat_main(void *unused)
34:{
35:   (void)unused;
36:   int jwks_ready = 0;
37:   while (atomic_load(&g_running))
38:   {
39:      char server_id[128];
40:      int ready = server_runtime_server_id_load(server_id, sizeof(server_id)) &&
41:                  kb_client_mtls_configured();
42:      if (ready)
43:      {
44:         if (kb_client_mtls_heartbeat(server_id, "ready", AIMEE_VERSION) != 0)
45:            LOG_WARN("server.kb", "server registry heartbeat rejected for %s", server_id);
46:         else if (!jwks_ready && management_jwks_ready())
47:         {
48:            jwks_ready = 1;
49:            LOG_INFO("server.mgmt", "management JWKS authorization ready");
50:         }
51:      }
52:      /* Before the wizard's one-shot writes the identity, poll quickly. Once
53:       * enrolled, return to the ordinary 30-second registry cadence. */
54:      int interval = ready ? 30 : 1;
55:      for (int i = 0; i < interval && atomic_load(&g_running); i++)
56:      {
57:         struct timespec delay = {1, 0};
58:         nanosleep(&delay, NULL);
59:      }
60:   }
61:   return NULL;
62:}
